// The Episode registry (GLOSSARY): what `npm run registry` writes from the Episode folders. An Episode is
// its folder, `src/episodes/<slug>/` or, for an Event's copy, `src/episodes/by-event/<event>/<slug>/`,
// so the id list, the store's metadata records and the compositions are derived from the folders, keyed by Episode id,
// one generated file per tier (FE-007: lib may not import the store or a component). The tooling pages,
// `src/episodes/tooling/<slug>/`, are listed and composed the same way, by slug, apart from the Episodes. Each file is
// checked in, so `tsc` reads the records where they are written, and a fast test fails when one is stale. The disk
// side lives in registry.ts, which walks the folders with the one folder walker (`src/episodes/lib/episode-folders.ts`).
import { METADATA_FILE, TOOLING_FOLDER, type PageFolder } from '../../src/episodes/lib/episode-folders.ts';

/**
 * One page folder the walker found: its Episode id (a tooling page's slug), its path under the Episodes folder,
 * `tooling/<slug>` for a tooling page, its entries, and its `episode.ts` text.
 */
export type EpisodeFolder = Pick<PageFolder, 'id' | 'folder' | 'files'> & { readonly episodeSource?: string };

/** One generated file: its path from the repository root, and its whole text. */
export interface RegistryFile {
  readonly path: string;
  readonly text: string;
}

/** Where each tier's registry lives. */
export const REGISTRY_PATHS = {
  ids: 'src/content-store/catalogue/episode-ids.generated.ts',
  metadata: 'src/content-store/episode-registry.generated.ts',
  compositions: 'src/episodes/lib/episode-registry.generated.ts',
} as const;

/** A tooling page's folder under the Episodes folder starts with this, one folder each. */
const TOOLING_PREFIX = `${TOOLING_FOLDER}/`;

const RECORD_FILE = 'episode.ts';
const HEADER = [
  '// The Episode registry, generated by `npm run registry` from the Episode folders: never edit by hand. A',
  '// folder `src/episodes/<slug>/` or `…/by-event/<event>/<slug>/` holding `episode-metadata.ts` is an',
  '// Episode, keyed by its id; with `episode.ts`, a page. A folder `src/episodes/tooling/<slug>/` is a tooling page.',
].join('\n');
const ID_TYPES = [
  "import type { EpisodeSlugOf } from '@/content-store/catalogue/episode-id.pure';",
  "import type { EpisodeId } from '@/content-store/catalogue/record-routes';",
].join('\n');

/** An Episode with a page: its id, its folder, the identifier it is imported under, and the name its `episode.ts` exports. */
interface RegisteredEpisode {
  readonly id: string;
  readonly folder: string;
  readonly local: string;
  readonly exported: string;
}

/** The identifier an id is imported under: `ai-token-economy` → `aiTokenEconomy`, `2026-…-axel__intro` → `_2026…Axel__intro`. */
function identifierOf(id: string): string {
  const camel = id.replace(/-([a-z0-9])/g, (_, next: string) => next.toUpperCase());
  return /^[0-9]/.test(camel) ? `_${camel}` : camel;
}

/** The one Episode record an `episode.ts` exports, as `export const <name> = episode({`. */
function exportedRecord(folder: EpisodeFolder): string {
  const names = [...(folder.episodeSource ?? '').matchAll(/export const (\w+)\s*=\s*episode\(/g)].map(
    ([, name]) => name,
  );
  if (names.length !== 1)
    throw new Error(
      `${folder.folder}/${RECORD_FILE} must export exactly one Episode record, \`export const <name> = episode({…})\`; found ${names.length}`,
    );
  return names[0];
}

/** Code-point order of ids, so the registry is the same on every machine whatever its locale. */
function byId(a: { readonly id: string }, b: { readonly id: string }): number {
  if (a.id === b.id) return 0;
  return a.id < b.id ? -1 : 1;
}

/** One map entry per Episode, keyed by its id. */
function entries(episodes: readonly { readonly id: string; readonly local: string }[]): string {
  return episodes.map(({ id, local }) => `  '${id}': ${local},`).join('\n');
}

function importOf({ local, exported }: RegisteredEpisode, from: string): string {
  return `import { ${exported === local ? local : `${exported} as ${local}`} } from '${from}';`;
}

function idsFile(episodes: readonly RegisteredEpisode[], tooling: readonly RegisteredEpisode[]): string {
  const ids = episodes.map(({ id }) => `'${id}'`).join(', ');
  const slugs = tooling.map(({ id }) => `'${id}'`).join(', ');
  return `${HEADER}

/** Every Episode with a page, public or unlisted, by Episode id: \`<slug>\`, or \`<event-slug>__<slug>\` for an Event's copy. */
export const EPISODE_IDS = [${ids}] as const;

/** Every tooling page, by slug: an authoring bench served at \`/episodes/<slug>/\`, no Episode (design-ADR 0016 decision 12). */
export const TOOLING_SLUGS = [${slugs}] as const;
`;
}

function metadataFile(episodes: readonly RegisteredEpisode[], upcoming: readonly EpisodeFolder[]): string {
  const asMetadata = ({ id, folder }: { id: string; folder: string }) => ({
    id,
    folder,
    local: identifierOf(id),
    exported: 'episodeMetadata',
  });
  const imports = [...episodes.map(asMetadata), ...upcoming.map(asMetadata)]
    .sort(byId)
    .map((each) => importOf(each, `@/episodes/${each.folder}/episode-metadata`));
  const upcomingEntries = upcoming.map(({ id }) => `'${id}': ${identifierOf(id)}`).join(', ');
  return `${HEADER}
${ID_TYPES}
import type { EpisodeInput } from './schemas/episode.schema';
${imports.join('\n')}

/** Every Episode with a page, public or unlisted: its metadata by id, so a record's slug must be its folder's name. */
export const EPISODE_METADATA = {
${entries(episodes)}
} as const satisfies { readonly [I in EpisodeId]: EpisodeInput & { readonly slug: EpisodeSlugOf<I> } };

/** Upcoming Episodes without a page, by id: each folder holding only its metadata. */
export const UPCOMING_METADATA: Readonly<Record<string, EpisodeInput>> = { ${upcomingEntries} };
`;
}

function compositionsFile(episodes: readonly RegisteredEpisode[], tooling: readonly RegisteredEpisode[]): string {
  const imports = [...episodes, ...tooling].map((each) => importOf(each, `@/episodes/${each.folder}/episode`));
  return `${HEADER}
import type { EpisodeComposition } from '@/episodes/components/slide-master/slide';
import type { EpisodeSlugOf } from '@/content-store/catalogue/episode-id.pure';
import type { EpisodeId, ToolingSlug } from '@/content-store/catalogue/record-routes';
${imports.join('\n')}

/** Every Episode's composition by id, so a record's slug must be its folder's name. */
export const EPISODES: { readonly [I in EpisodeId]: EpisodeComposition & { readonly slug: EpisodeSlugOf<I> } } = {
${entries(episodes)}
};

/** Every tooling page's Slides by slug: composed like an Episode, rendered by the same container, but no Episode. */
export const TOOLING_PAGES: { readonly [S in ToolingSlug]: EpisodeComposition & { readonly slug: S } } = {
${entries(tooling)}
};
`;
}

function registered(each: EpisodeFolder): RegisteredEpisode {
  return { id: each.id, folder: each.folder, local: identifierOf(each.id), exported: exportedRecord(each) };
}

/**
 * The three registry files for the given folders. A folder under `tooling/` is a tooling page, listed and composed by
 * its slug and kept out of the Episodes. Elsewhere a folder without `episode-metadata.ts` is no Episode and is left out;
 * one with metadata but no `episode.ts` is an upcoming Episode without a page. Order is id.
 */
export function episodeRegistryFiles(folders: readonly EpisodeFolder[]): readonly RegistryFile[] {
  const tooling = folders
    .filter(({ folder }) => folder.startsWith(TOOLING_PREFIX))
    .sort(byId)
    .map(registered);
  const sorted = folders
    .filter(({ folder, files }) => !folder.startsWith(TOOLING_PREFIX) && files.includes(METADATA_FILE))
    .sort(byId);
  const episodes = sorted.filter(({ files }) => files.includes(RECORD_FILE)).map(registered);
  const upcoming = sorted.filter(({ files }) => !files.includes(RECORD_FILE));
  return [
    { path: REGISTRY_PATHS.ids, text: idsFile(episodes, tooling) },
    { path: REGISTRY_PATHS.metadata, text: metadataFile(episodes, upcoming) },
    { path: REGISTRY_PATHS.compositions, text: compositionsFile(episodes, tooling) },
  ];
}
